#include "App/Diagnostics.h"
#include "App/AppPaths.h"
#include <thread>
#include <iostream>
#include <cstdlib>
#include <new>
namespace {thread_local bool probe=false;std::atomic<int> allocations{0};int checks=0;void expect(bool ok,const char* message){if(!ok)throw std::runtime_error(message);++checks;std::cout<<"PASS: "<<message<<'\n';}}
void* operator new(size_t n){if(probe)++allocations;if(auto* p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void operator delete(void* p)noexcept{std::free(p);}void operator delete(void* p,size_t)noexcept{std::free(p);}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI gui;try{expect(argc==2,"diagnostic fixture path supplied");const auto root=juce::File(juce::String::fromUTF8(argv[1])).getChildFile("caminho com acento ç-"+juce::Uuid().toString());_wputenv_s(L"NOVA_DAW_DATA_DIR",root.getFullPathName().toWideCharPointer());expect(nova::AppPaths::data()==root&&nova::AppPaths::workspace().isAChildOf(root)&&nova::AppPaths::workspace().isDirectory(),"user data and unsaved workspace are writable and independent of developer cwd");
    {nova::Diagnostics logger;const auto payload=juce::String::fromUTF8("RT message: áudio e parâmetros");std::array<std::thread,4> producers;for(auto& thread:producers)thread=std::thread([&]{probe=true;for(int n=0;n<200;++n)logger.logMessage(payload);probe=false;});for(auto& thread:producers)thread.join();expect(logger.dropped()>0,"bounded concurrent logging reports overflow instead of waiting or growing");expect(allocations==0,"log producer copies UTF8 without observed C++ new");logger.flush();const auto text=nova::Diagnostics::directory().getChildFile("nova.log").loadFileAsString();bool valid=true;int records=0;for(const auto& line:juce::StringArray::fromLines(text))if(line.isNotEmpty()){valid=valid&&juce::JSON::parse(line).isObject();++records;}expect(valid&&records>1&&text.contains("parâmetros")&&text.contains("logOverflowTotal"),"concurrent records persist as valid UTF8 JSONL and explicit overflow count");
    for(int i=0;i<20;++i)expect(nova::Diagnostics::report("test","Error "+juce::String(i)).existsAsFile(),"real diagnostic error report can be read from disk");expect(nova::Diagnostics::directory().findChildFiles(juce::File::findFiles,false,"error-*.json").size()<=16,"error report retention is bounded and does not remove session data");const auto sentinel=root.getChildFile("original-source.dat");sentinel.replaceWithText("preserve");{auto stream=nova::Diagnostics::directory().getChildFile("nova.log").createOutputStream();stream->setPosition(0);stream->writeRepeatedByte('x',2*1024*1024);}logger.flush();expect(nova::Diagnostics::directory().getChildFile("nova.1.log").existsAsFile()&&sentinel.loadFileAsString()=="preserve","rotation keeps previous log and preserves user sources");}
    expect(bool(juce::JSON::parse(nova::Diagnostics::directory().getChildFile("last-run.json"))["cleanExit"]),"normal shutdown records clean exit");expect(juce::Logger::getCurrentLogger()==nullptr,"shutdown detaches logger before freeing queue");std::cout<<checks<<" diagnostic checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
